			if r.score != 0 || r.depth != 3 || !slices.ContainsFunc(p.ValidMoves(), func(m chess.Move) bool { return m.String() == r.move }) {
				t.Fatal("root", p, r)
			}
			ctx, cancel := context.WithCancel(context.Background())
			cancel()
			if _, ok := (&searcher{ctx: ctx}).search(p, 2, -searchInfinity, searchInfinity, false); ok {
				t.Fatal("cancel")
