		"k3r3/8/8/3pP3/8/8/8/4K3 w - d6 0 1",
		"r6k/1P6/8/8/8/8/8/7K w - - 0 1",
		"8/k1P5/2K5/8/8/8/8/8 w - - 0 1",
		"7r/8/8/8/8/6k1/8/6BK w - - 0 1",
		"7k/5K2/6Q1/8/8/8/8/8 b - - 0 1",
		"7k/6Q1/5K2/8/8/8/8/8 b - - 0 1",
	}
