package chess

import "testing"

func TestSearchDeadMaterialAgainstGameSubset(t *testing.T) {
	checks := 0
	check := func(m map[Square]Piece, want bool) {
		t.Helper()
		b, err := NewBoard(m)
		if err != nil {
			t.Fatal(err)
		}
		p := &Position{board: b}
		if got := p.SearchDeadMaterial(); got != want || got == b.hasSufficientMaterial() {
			t.Fatalf("material %v: got %v want %v game sufficient %v", m, got, want, b.hasSufficientMaterial())
		}
		checks++
	}
	check(map[Square]Piece{A1: WhiteKing, H8: BlackKing}, true)
	for s := A1; s <= H8; s++ {
		if s == A1 || s == H8 {
			continue
		}
		for _, p := range []Piece{WhiteBishop, BlackBishop, WhiteKnight, BlackKnight, WhitePawn, BlackPawn, WhiteRook, BlackRook, WhiteQueen, BlackQueen} {
			check(map[Square]Piece{A1: WhiteKing, H8: BlackKing, s: p}, p.Type() == Bishop || p.Type() == Knight)
		}
		for u := s + 1; u <= H8; u++ {
			if u == H8 {
				continue
			}
			for _, pair := range [][2]Piece{{WhiteBishop, WhiteBishop}, {WhiteBishop, BlackBishop}, {BlackBishop, BlackBishop}, {WhiteKnight, WhiteKnight}, {WhiteKnight, BlackKnight}, {WhiteBishop, BlackKnight}} {
				want := pair[0].Type() == Bishop && pair[1].Type() == Bishop && s.color() == u.color()
				check(map[Square]Piece{A1: WhiteKing, H8: BlackKing, s: pair[0], u: pair[1]}, want)
			}
		}
	}
	// Multiple promoted bishops remain dead only when all share one colour.
	check(map[Square]Piece{A1: WhiteKing, H8: BlackKing, B2: WhiteBishop, D4: BlackBishop, F6: WhiteBishop}, true)
	check(map[Square]Piece{A1: WhiteKing, H8: BlackKing, B2: WhiteBishop, D4: BlackBishop, F5: WhiteBishop}, false)
	for _, m := range []map[Square]Piece{{A1: WhiteKing}, {A1: WhiteKing, B1: WhiteKing, H8: BlackKing}, {H8: BlackKing}} {
		b, err := NewBoard(m)
		if err != nil {
			t.Fatal(err)
		}
		if (&Position{board: b}).SearchDeadMaterial() {
			t.Fatalf("malformed kings %v", m)
		}
	}
	t.Logf("%d independent map/game material comparisons", checks)
}

func TestSearchDeadMaterialDoesNotAllocate(t *testing.T) {
	for _, fen := range []string{"8/7k/8/8/3B4/8/8/K7 w - - 0 1", "rnbqkbnr/pppppppp/8/8/8/8/PPPPPPPP/RNBQKBNR w KQkq - 0 1"} {
		opt, err := FEN(fen)
		if err != nil {
			t.Fatal(err)
		}
		p := NewGame(opt).Position()
		if n := testing.AllocsPerRun(100, func() { p.SearchDeadMaterial() }); n != 0 {
			t.Fatal(n)
		}
	}
}

