var (
	pieceUnicodes     = [13]string{" ", "♔", "♕", "♖", "♗", "♘", "♙", "♚", "♛", "♜", "♝", "♞", "♟"}
	pieceDarkUnicodes = [13]string{" ", "♚", "♛", "♜", "♝", "♞", "♟", "♔", "♕", "♖", "♗", "♘", "♙"}
)

// getFENChar returns the FEN character representation of a piece
