func (p Piece) getFENChar() byte {
	pieceType := p.Type()
	if pieceType < 0 || pieceType > 6 {
		return 0 // Invalid piece type
	}

	if p.Color() == White {
		return whitePiecesToFEN[pieceType]
	}
	return blackPiecesToFEN[pieceType]
