package chess

import "math/bits"

// SearchDeadMaterial proves a conservative subset of dead positions: bare
// kings, one bishop or knight in total, or bishops confined to one square
// colour without knights. It does not solve every dead position. Extra/missing
// kings are rejected so malformed test boards do not acquire draw semantics.
func (pos *Position) SearchDeadMaterial() bool {
	b := pos.board
	if b.bbWhitePawn|b.bbBlackPawn|b.bbWhiteRook|b.bbBlackRook|b.bbWhiteQueen|b.bbBlackQueen != 0 {
		return false
	}
	if bits.OnesCount64(uint64(b.bbWhiteKing)) != 1 || bits.OnesCount64(uint64(b.bbBlackKing)) != 1 {
		return false
	}
	bishops := uint64(b.bbWhiteBishop | b.bbBlackBishop)
	knights := uint64(b.bbWhiteKnight | b.bbBlackKnight)
	if knights != 0 {
		return bishops == 0 && bits.OnesCount64(knights) == 1
	}
	const colour = uint64(0xaa55aa55aa55aa55)
	return bishops&colour == 0 || bishops & ^colour == 0
}

